script.setup:
// Rapier (Rust compiled to WebAssembly) simulates a three-armed spiral of
// dominoes; one instanced draw renders them from the bodies' poses.
const mod = await ctx.utils.import("https://esm.sh/@dimforge/rapier3d-compat@0.20.0");
const RAPIER = mod.default ?? mod;
await RAPIER.init();
const gl = ctx.gl;
const HX = 0.06, HY = 0.4, HZ = 0.2, STEP = 0.36, ARMS = 3;
// Lay the dominoes along three spiral arms, thin side along the path.
const layout = [];
for (let arm = 0; arm < ARMS; arm++) {
  let th = 0.0, prev = null;
  const r = (t) => 0.7 + 0.42 * t, at = (t) => { const a = t + arm * Math.PI * 2 / ARMS; return [r(t) * Math.cos(a), r(t) * Math.sin(a)]; };
  for (let i = 0; th < 11; i++) {
    const p = at(th), q = at(th + 0.01);
    const yaw = Math.atan2(-(q[1] - p[1]), q[0] - p[0]);
    layout.push({ x: p[0], z: p[1], yaw, arm, k: i });
    th += STEP / Math.hypot(0.42, r(th)); // advance by arc length
  }
}
const COUNT = layout.length;
let world = null, bodies = [];
const build = (gravity) => {
  world?.free();
  world = new RAPIER.World({ x: 0, y: -9.81 * gravity, z: 0 });
  world.createCollider(RAPIER.ColliderDesc.cuboid(30, 0.1, 30).setTranslation(0, -0.1, 0).setFriction(0.8));
  bodies = layout.map((d) => {
    const s = Math.sin(d.yaw / 2), c = Math.cos(d.yaw / 2);
    const body = world.createRigidBody(RAPIER.RigidBodyDesc.dynamic().setTranslation(d.x, HY, d.z).setRotation({ x: 0, y: s, z: 0, w: c }).setCanSleep(true));
    world.createCollider(RAPIER.ColliderDesc.cuboid(HX, HY, HZ).setFriction(0.45).setDensity(2), body);
    return body;
  });
  // Tip the first domino of each arm outward along its path.
  layout.forEach((d, i) => {
    if (d.k !== 0) return;
    const fx = Math.cos(d.yaw), fz = -Math.sin(d.yaw);
    bodies[i].applyImpulseAtPoint({ x: fx * 0.12, y: 0, z: fz * 0.12 }, { x: d.x, y: HY * 1.9, z: d.z }, true);
  });
  ctx.state.world = world; ctx.state.bodies = bodies;
};
const box = ctx.utils.createMesh(ctx.utils.geometry.box());
const inst = new Float32Array(COUNT * 12), buf = gl.createBuffer();
gl.bindVertexArray(box.vao);
gl.bindBuffer(gl.ARRAY_BUFFER, buf);
gl.bufferData(gl.ARRAY_BUFFER, inst.byteLength, gl.DYNAMIC_DRAW);
for (let c = 0; c < 3; c++) { gl.enableVertexAttribArray(3 + c); gl.vertexAttribPointer(3 + c, 4, gl.FLOAT, false, 48, c * 16); gl.vertexAttribDivisor(3 + c, 1); }
gl.bindVertexArray(null);
const prog = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec3 a_position; layout(location=1) in vec3 a_normal;
layout(location=3) in vec4 a_pos; layout(location=4) in vec4 a_rot; layout(location=5) in vec4 a_info;
uniform mat4 u_vp; uniform vec3 u_half; out vec3 v_n; out vec3 v_w; out vec4 v_info;
vec3 qrot(vec4 q, vec3 v) { return v + 2.0 * cross(q.xyz, cross(q.xyz, v) + q.w * v); }
void main() {
  vec3 p = qrot(a_rot, a_position * u_half * 2.0) + a_pos.xyz;
  v_w = p; v_n = qrot(a_rot, a_normal); v_info = a_info;
  gl_Position = u_vp * vec4(p, 1.0);
}`, `#version 300 es
precision highp float; in vec3 v_n; in vec3 v_w; in vec4 v_info; out vec4 outColor;
uniform vec3 u_eye, u_colorA, u_colorB; uniform float u_floor;
void main() {
  vec3 n = normalize(v_n), v = normalize(u_eye - v_w), l = normalize(vec3(0.4, 0.9, 0.3));
  vec3 base = mix(u_colorA, u_colorB, v_info.x);
  // Fallen dominoes light up.
  base *= 0.55 + 0.6 * v_info.y;
  if (u_floor > 0.5) base = mix(vec3(0.016, 0.017, 0.023), vec3(0.0004, 0.0005, 0.0008), smoothstep(2.0, 11.0, length(v_w.xz)));
  float d = max(dot(n, l), 0.0), sp = pow(max(dot(n, normalize(l + v)), 0.0), 50.0) * (1.0 - u_floor);
  vec3 c = base * (0.2 + 0.8 * d) + sp * 0.4;
  outColor = vec4(pow(c, vec3(0.4545)), 1.0);
}`);
// The floor is the same box without instance buffers (it reads constant attributes instead).
const floorMesh = ctx.utils.createMesh(ctx.utils.geometry.box());
Object.assign(ctx.state, { RAPIER, build, floorMesh, layout, inst, buf, box, prog, COUNT, HX, HY, HZ, clock: 0, gravity: 0, doneAt: 0,
  camera: ctx.utils.createOrbitCamera({ distance: 15, theta: 0.3, phi: 0.75 }) });
build(1);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
if (s.gravity !== u.u_gravity || u.u_reset) { s.gravity = u.u_gravity; s.build(u.u_gravity); s.clock = 0; s.doneAt = 0; }
s.world.timestep = 1 / 60;
// Fixed steps, at most a few per frame.
s.clock += Math.min(ctx.dt, 0.1);
s.sim ??= 0;
let steps = 0;
while (s.sim < s.clock && steps++ < 4) { s.world.step(); s.sim += 1 / 60; }
if (steps >= 4) s.sim = s.clock;
let fallen = 0;
s.bodies.forEach((b, i) => {
  const p = b.translation(), q = b.rotation(), d = s.layout[i];
  // How far the domino has tipped: its local up axis vs world up.
  const upY = 1 - 2 * (q.x * q.x + q.z * q.z), tip = Math.min(1, Math.max(0, 1 - upY) * 1.5);
  if (upY < 0.5) fallen++;
  s.inst.set([p.x, p.y, p.z, 0, q.x, q.y, q.z, q.w, (d.arm + d.k / 100) / 3 % 1, tip, 0, 0], i * 12);
});
// Start over a little after everything has fallen.
if (fallen > s.COUNT * 0.97 && !s.doneAt) s.doneAt = s.clock;
if (s.doneAt && s.clock - s.doneAt > 2.5 || s.clock > 60) { s.build(u.u_gravity); s.clock = s.sim = 0; s.doneAt = 0; }
gl.bindBuffer(gl.ARRAY_BUFFER, s.buf);
gl.bufferSubData(gl.ARRAY_BUFFER, 0, s.inst);
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const vp = mat4.multiply(s.camera.getProjectionMatrix(w / h, 40, 0.1, 100), s.camera.getViewMatrix());
gl.enable(gl.DEPTH_TEST);
gl.clearColor(0.025, 0.027, 0.035, 1);
gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.prog);
ctx.utils.setUniforms(s.prog, { u_vp: vp, u_eye: s.camera.getEye(), u_colorA: u.u_colorA, u_colorB: u.u_colorB, u_floor: 0, u_half: [s.HX, s.HY, s.HZ] });
s.box.draw(gl.TRIANGLES, s.COUNT);
ctx.utils.setUniforms(s.prog, { u_floor: 1, u_half: [30, 0.1, 30] });
gl.vertexAttrib4f(3, 0, -0.1, 0, 0); gl.vertexAttrib4f(4, 0, 0, 0, 1); gl.vertexAttrib4f(5, 0, 0, 0, 0);
s.floorMesh.draw();
ctx.publish("dominoes", s.COUNT);
ctx.publish("fallen", fallen);
